import{c as t,Q as o,j as a,m as r}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"Remote Access Without Relay Tunnel","description":"","frontmatter":{},"headers":[],"relativePath":"hub/remote-access.md","filePath":"hub/remote-access.md"}'),i={name:"hub/remote-access.md"};function s(n,e,l,d,p,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="remote-access-without-relay-tunnel" tabindex="-1">Remote Access Without Relay Tunnel <a class="header-anchor" href="#remote-access-without-relay-tunnel" aria-label="Permalink to &quot;Remote Access Without Relay Tunnel&quot;">​</a></h1><p>Phlix Media Server supports direct internet access to your media library without requiring the relay tunnel. This guide explains how to set up and verify direct connectivity.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>When your server is reachable from the internet directly (via port forwarding on your router), clients can connect straight to your server rather than going through the relay tunnel. This typically provides:</p><ul><li>Lower latency for playback</li><li>Higher quality streams (no transcoding at relay)</li><li>Reduced infrastructure dependency</li></ul><h2 id="how-port-forwarding-works" tabindex="-1">How Port Forwarding Works <a class="header-anchor" href="#how-port-forwarding-works" aria-label="Permalink to &quot;How Port Forwarding Works&quot;">​</a></h2><h3 id="upnp-igd-universal-plug-and-play-internet-gateway-device" tabindex="-1">UPnP-IGD (Universal Plug and Play - Internet Gateway Device) <a class="header-anchor" href="#upnp-igd-universal-plug-and-play-internet-gateway-device" aria-label="Permalink to &quot;UPnP-IGD (Universal Plug and Play - Internet Gateway Device)&quot;">​</a></h3><p>UPnP-IGD allows devices on your LAN to automatically configure port mappings on your router. Phlix uses this to:</p><ol><li><strong>Discovery</strong> — Sends an SSDP M-SEARCH multicast to <code>239.255.255.250:1900</code> to find UPnP-capable routers.</li><li><strong>External IP detection</strong> — Queries the router&#39;s <code>GetExternalIPAddress</code> SOAP action.</li><li><strong>Port mapping</strong> — Calls <code>AddPortMapping</code> to open the configured port (default: 32400) on the router.</li></ol><h3 id="nat-pmp-nat-port-mapping-protocol" tabindex="-1">NAT-PMP (NAT Port Mapping Protocol) <a class="header-anchor" href="#nat-pmp-nat-port-mapping-protocol" aria-label="Permalink to &quot;NAT-PMP (NAT Port Mapping Protocol)&quot;">​</a></h3><p>For Apple AirPort routers and other NAT-PMP-compatible devices, Phlix falls back to RFC 6886 NAT-PMP:</p><ol><li>Sends a public address request to the router&#39;s LAN IP on UDP port 5350.</li><li>Uses the response to determine the external IP.</li><li>Sends a map request to open the port.</li></ol><h3 id="stun-session-traversal-utilities-for-nat" tabindex="-1">STUN (Session Traversal Utilities for NAT) <a class="header-anchor" href="#stun-session-traversal-utilities-for-nat" aria-label="Permalink to &quot;STUN (Session Traversal Utilities for NAT)&quot;">​</a></h3><p>STUN (RFC 5389) is used to:</p><ol><li><strong>Discover your public IP</strong> — Sends a binding request to <code>stun.l.google.com:19302</code> (configurable) and reads the XOR-MAPPED-ADDRESS from the response.</li><li><strong>Test port accessibility</strong> — Attempts a TCP connection to your public IP on the configured port to verify the mapping is working.</li></ol><h2 id="setting-up-port-forwarding" tabindex="-1">Setting Up Port Forwarding <a class="header-anchor" href="#setting-up-port-forwarding" aria-label="Permalink to &quot;Setting Up Port Forwarding&quot;">​</a></h2><h3 id="automatic-recommended" tabindex="-1">Automatic (Recommended) <a class="header-anchor" href="#automatic-recommended" aria-label="Permalink to &quot;Automatic (Recommended)&quot;">​</a></h3><p>Run the port-forward script with <code>enable</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/port-forward.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span></code></pre></div><p>If UPnP is available on your router, the script will automatically open the port and report the public endpoint.</p><h3 id="manual-configuration" tabindex="-1">Manual Configuration <a class="header-anchor" href="#manual-configuration" aria-label="Permalink to &quot;Manual Configuration&quot;">​</a></h3><p>If automatic discovery fails, you can configure port forwarding manually:</p><ol><li><p>Log in to your router&#39;s admin panel (typically <code>http://192.168.1.1</code> or <code>http://192.168.0.1</code>).</p></li><li><p>Find <strong>Port Forwarding</strong>, <strong>NAT</strong>, or <strong>Firewall</strong> settings.</p></li><li><p>Create a new rule:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td>TCP</td></tr><tr><td>Ext Port</td><td>32400 (or your choice)</td></tr><tr><td>Int Port</td><td>32400</td></tr><tr><td>Int IP</td><td>Your server&#39;s LAN IP</td></tr></tbody></table></li><li><p>Save and apply. Your router may need a restart.</p></li></ol><p>To find your server&#39;s LAN IP, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/port-forward.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span></code></pre></div><h3 id="verify-the-port-is-open" tabindex="-1">Verify the Port is Open <a class="header-anchor" href="#verify-the-port-is-open" aria-label="Permalink to &quot;Verify the Port is Open&quot;">​</a></h3><p>After configuring, verify your port is accessible:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/port-forward.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span></code></pre></div><p>Look for the <code>Port 32400 on &lt;public-ip&gt;</code> line. It should show <code>OPEN</code> if the mapping succeeded.</p><p>You can also use an external port checker like <a href="https://www.yougetsignal.com/tools/open-ports/" target="_blank" rel="noreferrer">you-get-signal.com</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="upnp-discovery-fails" tabindex="-1">UPnP Discovery Fails <a class="header-anchor" href="#upnp-discovery-fails" aria-label="Permalink to &quot;UPnP Discovery Fails&quot;">​</a></h3><ul><li><strong>Cause:</strong> Router does not support UPnP-IGD or has it disabled.</li><li><strong>Fix:</strong> Enable UPnP in your router&#39;s settings, or use manual port forwarding.</li></ul><h3 id="port-shows-blocked-filtered" tabindex="-1">Port Shows BLOCKED/FILTERED <a class="header-anchor" href="#port-shows-blocked-filtered" aria-label="Permalink to &quot;Port Shows BLOCKED/FILTERED&quot;">​</a></h3><ul><li><strong>Cause:</strong> Router did not apply the port mapping, or a firewall is blocking the port.</li><li><strong>Fix:</strong> Verify the port forwarding rule is active in your router. Check that your server&#39;s firewall allows incoming connections on the configured port.</li></ul><h3 id="stun-returns-no-public-ip" tabindex="-1">STUN Returns No Public IP <a class="header-anchor" href="#stun-returns-no-public-ip" aria-label="Permalink to &quot;STUN Returns No Public IP&quot;">​</a></h3><ul><li><strong>Cause:</strong> Firewall or symmetric NAT preventing STUN from working.</li><li><strong>Fix:</strong> Use manual port forwarding and ensure your router supports UPnP or NAT-PMP.</li></ul><h2 id="using-with-the-hub" tabindex="-1">Using with the Hub <a class="header-anchor" href="#using-with-the-hub" aria-label="Permalink to &quot;Using with the Hub&quot;">​</a></h2><p>When direct access is available, your server includes hostname candidates in heartbeats to the hub:</p><ul><li><code>http://&lt;lan-ip&gt;:32400</code> — Local network access</li><li><code>http://phlix.local:32400</code> — mDNS/local hostname</li><li><code>http://&lt;public-ip&gt;:32400</code> — Direct internet access (when port is open)</li></ul><p>The hub uses these candidates to determine the best connection method for clients.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><code>docs/hub-admin/network.md</code> — Network configuration for hub administrators</li><li><code>php scripts/port-forward.php help</code> — All port-forward commands</li><li><code>docs/dev/relay-protocol.md</code> — Relay tunnel protocol (fallback when direct access is unavailable)</li></ul>',43)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
